"""Mandelbrot escape times computed on the GPU with wgpu, summarized on stdout."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> xs: array<f32>;
@group(0) @binding(2) var<storage, read> ys: array<f32>;
@group(0) @binding(3) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    let j = gid.y;
    if (i >= params.width || j >= params.height) {
        return;
    }
    let cx = xs[i];
    let cy = ys[j];
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    out[j * params.width + i] = n;
}
"""


def parse_input(path):
    with open(path) as f:
        lines = [line.split() for line in f.read().splitlines() if line.strip()]
    if len(lines) < 2 or len(lines[0]) != 3 or len(lines[1]) != 4:
        raise ValueError("expected '<width> <height> <limit>' and '<x_min> <x_max> <y_min> <y_max>'")
    width, height, limit = (int(v) for v in lines[0])
    x_min, x_max, y_min, y_max = (float(v) for v in lines[1])
    if not (1 <= width <= 1024 and 1 <= height <= 1024 and 1 <= limit <= 1000):
        raise ValueError("width/height must be in 1..1024 and limit in 1..1000")
    if not (x_min < x_max and y_min < y_max):
        raise ValueError("bounds must satisfy x_min < x_max and y_min < y_max")
    return width, height, limit, x_min, x_max, y_min, y_max


def axis(lo, hi, count):
    """Coordinates of the cell centres along one axis, rounded once to f32."""
    k = np.arange(count, dtype=np.float64)
    return (lo + (k + 0.5) * (hi - lo) / count).astype(np.float32)


def escape_times_gpu(width, height, limit, x_min, x_max, y_min, y_max):
    """Run the escape-time kernel on the GPU; returns a (height, width) uint32 array."""
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    xs = axis(x_min, x_max, width)
    ys = axis(y_min, y_max, height)
    params = np.array([width, height, limit, 0], dtype=np.uint32)
    out_size = width * height * 4

    params_buf = device.create_buffer_with_data(data=params, usage=wgpu.BufferUsage.UNIFORM)
    xs_buf = device.create_buffer_with_data(data=xs, usage=wgpu.BufferUsage.STORAGE)
    ys_buf = device.create_buffer_with_data(data=ys, usage=wgpu.BufferUsage.STORAGE)
    out_buf = device.create_buffer(
        size=out_size, usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC
    )

    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": device.create_shader_module(code=SHADER), "entry_point": "main"},
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": params_buf.size}},
            {"binding": 1, "resource": {"buffer": xs_buf, "offset": 0, "size": xs_buf.size}},
            {"binding": 2, "resource": {"buffer": ys_buf, "offset": 0, "size": ys_buf.size}},
            {"binding": 3, "resource": {"buffer": out_buf, "offset": 0, "size": out_buf.size}},
        ],
    )

    encoder = device.create_command_encoder()
    compute_pass = encoder.begin_compute_pass()
    compute_pass.set_pipeline(pipeline)
    compute_pass.set_bind_group(0, bind_group)
    compute_pass.dispatch_workgroups(
        (width + WORKGROUP - 1) // WORKGROUP, (height + WORKGROUP - 1) // WORKGROUP, 1
    )
    compute_pass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(out_buf)
    return np.frombuffer(data, dtype=np.uint32).reshape(height, width)


def summarize(times, limit):
    times = np.asarray(times, dtype=np.int64).ravel()
    inside = int(np.count_nonzero(times == limit))
    escaped = times[times < limit]
    bins = np.bincount(8 * escaped // limit, minlength=8)[:8]
    mean = escaped.sum() / escaped.size if escaped.size else 0.0
    lines = [f"INSIDE {inside}"]
    lines += [f"BIN {b} {int(bins[b])}" for b in range(8)]
    lines.append(f"MEAN {mean:.3f}")
    return lines


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    width, height, limit, x_min, x_max, y_min, y_max = parse_input(argv[1])
    times = escape_times_gpu(width, height, limit, x_min, x_max, y_min, y_max)
    sys.stdout.write("\n".join(summarize(times, limit)) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

